      "لا يجب قبول الاستقرار الاقتصادي ما لم تتوقف الإصلاحات العامة عن كشف الفساد وإهمال الاستثمار.",
      "لا يمكن تحقيق الاستقرار الاقتصادي إلا إذا طُبقت إصلاحات شاملة للحد من الفساد وتشجيع ريادة الأعمال.",
      "يمكن تجنب الاستقرار المالي إذا ما ألغيت إصلاحات جزئية لزيادة الفساد ومحاربة رواد الأعمال."
