      "٢. 'curb' تعني يكبح أو يحد من، وليست زيادة أو دعم.",
      "٣. 'entrepreneurship' هو المصطلح المعتمد لـ 'ريادة الأعمال'.",
      "٤. الخيارات الثلاثة الأخرى تحرف المعنى وتبدل النفي إثباتاً والحد زيادة."
